    // Lista de errores sintácticos:
    private List<String> errores = new ArrayList<>();

    // Tabla de símbolos: scope -> lista de descripciones de símbolos.
    private HashMap<String, ArrayList<String>> tablaSimbolos = new HashMap<>();

    // Scope actual (por defecto "global").
    public String currentScope = "global";

    public Parser(Lexer s) {
        this.s = s;
    }

    // ---------------------------------------------------------------------
    // MÉTODOS PARA MANEJO DE ERRORES
    // ---------------------------------------------------------------------

    @Override
    public void syntax_error(Symbol sym) {
        report_error("Unexpected token", sym);
        // Intentar recuperación después de reportar el error
        recover_until_sync_point();
    }

    @Override
    public void unrecovered_syntax_error(Symbol cur_token) throws java.lang.Exception {
        // Log the error but don't throw exception
        System.err.println("Attempting to recover from unrecovered syntax error at token: "
                           + cur_token.value
                           + " (linea " + (cur_token.left+1)
                           + ", col " + (cur_token.right+1) + ")");

        // Try to recover by skipping tokens until a synchronization point
        recover_until_sync_point();
    }

    @Override
    public void report_fatal_error(String message, Object info) {
        if (info instanceof Symbol) {
            report_error(message, (Symbol)info);
        } else {
            System.err.println("Attempting to recover from fatal error: " + message);
        }
        // Try to recover instead of stopping
        recover_until_sync_point();
    }

    public void report_error(String message, Symbol sym) {
        if (sym != null) {
            String errorMsg = String.format(
                "Syntax Error: %s cerca del token '%s' en línea %d, columna %d",
                message, sym.value, sym.left + 1, sym.right + 1
            );
            errores.add(errorMsg);
            System.err.println(errorMsg);
        } else {
            String errorMsg = "Syntax Error: " + message;
            errores.add(errorMsg);
            System.err.println(errorMsg);
        }
    }

    // Nuevo método para recuperación mejorada
    private void recover_until_sync_point() {
        try {
            Symbol tok;
            // Lista de tokens de sincronización
            Set<Integer> sync_tokens = new HashSet<>(Arrays.asList(
                sym.PUNTO_Y_COMA,    // ;
                sym.CIERRACUENTO,    // }
                sym.CIERRAREGALO,    // )
                sym.FINREGALO,       // statement terminator
                sym.ELSE,            // tokens de control
                sym.CASE,
                sym.DEFAULT
            ));

            do {
                tok = s.next_token();
                // Continuar hasta encontrar un token de sincronización o EOF
                if (tok.sym == sym.EOF) {
                    System.err.println("Reached end of file during error recovery");
                    return;
                }
            } while (!sync_tokens.contains(tok.sym));

            System.out.println("Recovered at synchronization point: " + tok.value);

        } catch (Exception e) {
            System.err.println("Error during recovery: " + e.getMessage());
        }
    }

    // Mejorar el método sync_until_token existente
    public void sync_until_token(int syncToken) {
        try {
            Symbol tok;
            int skippedTokens = 0;
            do {
                tok = s.next_token();
                skippedTokens++;

                if (skippedTokens > 100) {  // Límite de seguridad
                    System.err.println("Warning: Skipped too many tokens during recovery");
                    return;
                }

                if (tok.sym == sym.EOF) {
                    System.err.println("Reached EOF during sync");
                    return;
                }
            } while (tok.sym != syncToken);

            System.out.println("Successfully synchronized to token: " + tok.value);

        } catch (Exception e) {
            System.err.println("Error in sync_until_token: " + e.getMessage());
        }
    }

    public List<String> getErrores() {
        return errores;
    }

    // ---------------------------------------------------------------------
    // MÉTODOS PARA TABLA DE SÍMBOLOS
    // ---------------------------------------------------------------------

    public void crearTabla(String type, String funcName, int line, int col) {
        System.out.println("/++Nueva tabla de símbolos++/ " + funcName);
        String infoFuncion = "tipoFuncion:" + type + " line:" + line + " col:" + col;

        ArrayList<String> nuevaLista = new ArrayList<>();
        nuevaLista.add(infoFuncion);

        currentScope = funcName;
        tablaSimbolos.put(currentScope, nuevaLista);
    }

    public void addSimbolo(String scope, String lexeme, int line, int col, String type) {
        if (!tablaSimbolos.containsKey(scope)) {
            tablaSimbolos.put(scope, new ArrayList<String>());
        }
        String info = "line:" + line
                    + " col:" + col
                    + " lex:" + lexeme
                    + " scope:" + scope
                    + " type:" + type;
        tablaSimbolos.get(scope).add(info);
        System.out.println("Se agregó símbolo -> " + info);
    }

    public void imprimirTablaSimbolos() {
        System.out.println("\n--- Tablas de Símbolos ---");
        for (String scopeKey : tablaSimbolos.keySet()) {
            System.out.println("Scope: " + scopeKey);
            for (String symInfo : tablaSimbolos.get(scopeKey)) {
                System.out.println("  " + symInfo);
            }
        }
    }


